/* Notifications */
.notification                                   { padding: 3px 10px; min-width: 200px; max-width: 400px; max-height: 200px; word-wrap: normal; word-break: keep-all; }
.notification > .k-icon                         { margin-right: 10px; }
.notification > *                               { display: inline-block; }

.k-widget.k-notification                        { border: none; background: white; box-shadow: none; }
.k-widget.k-notification > .notification        { margin-bottom: 10px; border-radius: 5px; }

/* validation helpers */
label.error                                     { font-weight: normal; width: 100%; display: block; }

/* forms */
.fieldList                                      { flex-direction: column; flex-wrap: wrap; padding: 7px; display: flex; flex:1; max-width: 600px; }
.fieldList > li                                 { padding: 5px; flex-direction: row; flex-wrap: wrap; flex:1; display:flex; justify-content: space-between; }
.fieldList > li > label                         { vertical-align: top; font-weight: bold; }
.fieldList > li > .value                        { flex-direction: column }
.fieldList > li > .value > .k-invalid           { border: dashed 1px red; }
.fieldList .k-widget.k-tooltip-validation       { border: 0; box-shadow: none; text-align: left; display: block; }

/* tables */
 th[role=columnheader]                           { font-weight: bold !important; }
.submenu li                                     { display: block; }

/* Context Menus */
.contextMenu                                    { position: fixed; display: none; top: 0; left: 0; }
.contextMenu > .component                       { margin: 0;}
.contextMenu > .component > ul > li             { padding: 10px; }
.contextMenu > .component > ul > li:hover       { background: #CCC; }
.contextMenu > .component > ul > li > .k-icon   { margin-right: 5px; margin-top: -3px; }

.contextMenu > ul > li                          { padding: 10px; }
.contextMenu > ul > li:hover                    { background: #CCC; }
.contextMenu > ul > li > .k-icon                { margin-right: 5px; margin-top: -3px; }

/* Content Management Editing */
.content[contenteditable]                       { outline: dashed 1px red; margin: 10px; padding: 10px; min-height: 20px; max-width: calc(100% - 20px); }
.content[contenteditable]:hover                 { outline: dashed 1px red; box-shadow: 4px 4px 4px; }
.content[contenteditable]:focus, 
.content[contenteditable]:active                { outline: solid 1px red; box-shadow: 4px 4px 4px; }
.editorToolbar                                  { border: none; background-color: transparent; max-width: 330px; }
.pageToolbar                                    { width: 100%; background-color: #f6f6f6; border-bottom: solid 1px #ccc; box-shadow: 4px 4px 4px; }
.pageToolbar > div                              { display: inline-block; height: 30px; }
.pageToolbar > .tools-left                      {  }
.pageToolbar > .tools-right                     { position: absolute; right: 0; }
.pageToolbar > .tools-right > *                 { display: inline-block; vertical-align: top; line-height: 30px; }


